Section FASTFACTS.
Variables (st : mstate) (LB : list block) (sc n : Z) (g : aptr) (k : Z) (t : N).
Let st1 := set_tick t st.
Let mr := get_meta_rec st g.
Let st2 := upd_meta g (m_set_avail (m_avail mr - 2 ^ k)) st1.
Hypothesis MF : ltac2:(zQ "20!mv7!sa@3$0@1$1?5HCEIL?2st?2LB").
Hypothesis ACT : ltac2:(zQ "50!iuf!o3!ng3!km5!ngc@3$1$4@2$2?2st?2sc@2$0$3?1g").
Hypothesis AV : 0 < m_avail mr.
Hypothesis K0 : ltac2:(zQ "10!h8@2$0Z?1k").
Hypothesis LBK : lowbit (m_avail mr) = 2 ^ k.
Hypothesis N0 : ltac2:(zQ "10!h8@2$0Z?1n").
Hypothesis NFIT : ltac2:(zQ "40!nh3!l2!h8!hm8@2$2@2$1?1n+4@2$3+h0@1$0?2sc").

Lemma rget_meta_rec_st2 : get_meta_rec st2 g = m_set_avail (m_avail mr - 2 ^ k) mr.
Proof.
